const items = $input.all();

const DOMINIO_PROPRIO = 'ateliersenzapari.com.br';
const PREFIXO_ROTEADO = '[roteado automaticamente]';
const PALAVRAS_FINANCEIRO = ['boleto', 'nota fiscal', 'das', 'honorarios', 'honorários'];
const REMETENTES_FINANCEIRO = ['anexoconsultoria.com.br'];
const PALAVRAS_VENDAS = ['pedido', 'produto', 'comprar', 'disponibilidade', 'preco', 'preço'];
const REMETENTES_LUCIANO = ['itau.com.br', 'bradesco.com.br', 'bb.com.br', 'gov.br', 'receita.fazenda.gov.br', 'hapvida.com.br'];

function normalizar(texto) {
  return (texto || '')
    .toString()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

return items.map((item) => {
  const json = item.json;

  const remetente = (json.from && json.from.value && json.from.value[0] && json.from.value[0].address) || json.from || '';
  const remetenteNome = (json.from && json.from.value && json.from.value[0] && json.from.value[0].name) || '';
  const assunto = json.subject || '';
  const corpo = json.textPlain || json.text || '';

  const remetenteNorm = normalizar(remetente);
  const assuntoNorm = normalizar(assunto);
  const textoNorm = normalizar(assunto + ' ' + corpo);

  let categoria = 'manual';

  // Todos os enderecos (contato@, vendas@, financeiro@, luciano@) caem na MESMA caixa.
  // Sem essa checagem, um e-mail encaminhado por este proprio workflow seria lido de
  // novo e reencaminhado outra vez, causando loop infinito.
  if (remetenteNorm.includes(DOMINIO_PROPRIO) || assuntoNorm.includes(PREFIXO_ROTEADO)) {
    categoria = 'interno';
  } else if (
    REMETENTES_FINANCEIRO.some((d) => remetenteNorm.includes(d)) ||
    PALAVRAS_FINANCEIRO.some((p) => textoNorm.includes(normalizar(p)))
  ) {
    categoria = 'financeiro';
  } else if (PALAVRAS_VENDAS.some((p) => textoNorm.includes(normalizar(p)))) {
    categoria = 'vendas';
  } else if (REMETENTES_LUCIANO.some((d) => remetenteNorm.includes(d))) {
    categoria = 'luciano';
  }

  return {
    json: {
      categoria,
      remetente,
      remetenteNome,
      assunto,
      corpo,
      data: json.date || new Date().toISOString()
    }
  };
});

